cache = {}
def load(rel):
    p = os.path.join(ROOT, rel)
    if rel not in cache:
        if not os.path.isfile(p):
            cache[rel] = None
        else:
            cache[rel] = open(p, "rb").read().decode("utf-8")
    return cache[rel]

changed = set(); skipped = []; applied = 0

# ---- 1) satir+kolon sabitli duzeltmeler (log'daki hata konumlari) ----
RULES = {
    "rotate":       (".rotate(",       ".mulPose("),
    "x_field":      (".x()",           ".x"),
    "z_field":      (".z()",           ".z"),
    "x_getter":     (".x()",           ".getX()"),
    "z_getter":     (".z()",           ".getZ()"),
    "mainCamera":   (".mainCamera()",  ".getMainCamera()"),
    "centeredText": (".centeredText(", ".drawCenteredString("),
}
by_file = {}
for f, l, col, kind, code in ANCHORS:
    by_file.setdefault(f, []).append((l, col, kind, code))
for rel, items in by_file.items():
    s = load(rel)
    if s is None:
        skipped.append((rel, "dosya yok")); continue
    lines = s.split("\n")
    # ayni satirda sagdan sola uygula ki kolonlar kaymasin
    for l, col, kind, code in sorted(items, key=lambda t: (t[0], -t[1])):
        old, new = RULES[kind]
        if l - 1 >= len(lines):
            skipped.append((rel + ":" + str(l), "satir yok")); continue
        line = lines[l - 1]
        if line[col:col + len(old)] == old:
            lines[l - 1] = line[:col] + new + line[col + len(old):]
            applied += 1; changed.add(rel)
        elif new in line[max(0, col - 2):col + len(new) + 2]:
            pass  # zaten uygulanmis
        elif old in line:
            skipped.append((rel + ":" + str(l), "kolon kaymis: " + old))
    cache[rel] = "\n".join(lines)

# ---- 2) genel regex duzeltmeler (26.x'e ozgu adlar, tum .java dosyalarinda) ----
GLOBAL = [
    # swing(hand, SwingAnimation.DEFAULT, false) -> swing(hand)
    (r"\.swing\(\s*([^,()]+(?:\([^()]*\))?)\s*,\s*(?:net\.minecraft\.world\.item\.component\.)?SwingAnimation\.DEFAULT\s*,\s*(?:false|true)\s*\)", r".swing(\1)"),
    (r"gameMode\.handleContainerInput\(", "gameMode.handleInventoryMouseClick("),
    (r"\.gui\.screen\(\)", ".screen"),
    (r"\.gui\.setScreen\(", ".setScreen("),
    (r"\.gui\.hud\b", ".gui"),
    (r"\bChunkPos\.pack\(", "ChunkPos.asLong("),
    (r"\b([\w.]+)\.getCurrentSwing\(\)\.hand\(\)", r"\1.swingingArm"),
    (r"\b([\w.]+)\.getCurrentSwing\(\) == null", r"!\1.swinging"),
    (r"\b([\w.]+)\.getCurrentSwing\(\) != null", r"\1.swinging"),
    (r",\s*net\.minecraft\.world\.level\.block\.BonemealSource\.INTERACTION\)", ")"),
    (r"\.getMainCamera\(\)\.position\(\)", ".getMainCamera().getPosition()"),
    (r"\.getMainCamera\(\)\.(?:yaw|yRot)\(\)", ".getMainCamera().getYRot()"),
    (r"\.getMainCamera\(\)\.(?:pitch|xRot)\(\)", ".getMainCamera().getXRot()"),
]
for dp, dn, fn in os.walk(ROOT):
    for n in fn:
        if not n.endswith(".java"): continue
        p = os.path.join(dp, n); rel = os.path.relpath(p, ROOT)
        s = load(rel)
        o = s
        for pat, rep in GLOBAL:
            s = re.sub(pat, rep, s)
        if s != o:
            cache[rel] = s; changed.add(rel)

# ---- 3) Screen alt siniflari: extractRenderState/extractBackground -> render/renderBackground ----
SCREEN_FILES = ["hex/api/baritone/utils/GuiClick.java", "sg/ec/AutoSwapWheelScreen.java",
                "sg/ec/AccountSwitcherScreen.java", "sg/ec/ProxyScreen.java", "sg/ec/MainMenuScreen.java"]
for rel in SCREEN_FILES:
    s = load(rel)
    if s is None:
        skipped.append((rel, "dosya yok")); continue
    o = s
    s = re.sub(r"(?<=[ .])extractRenderState\(", "render(", s)
    s = re.sub(r"(?<=[ .])extractBackground\(", "renderBackground(", s)
    if s != o:
        cache[rel] = s; changed.add(rel)

# ---- 4) MinecraftMixin_1211: Gui.screen() yerine @Shadow Minecraft.screen ----
rel = "sg/mx/MinecraftMixin_1211.java"
s = load(rel)
if s is not None and "this.screen" in s:
    if "public Screen screen;" not in s:
        nl = "\r\n" if "\r\n" in s else "\n"
        s = s.replace("   public Gui gui;", "   public Gui gui;" + nl + "   @Shadow" + nl + "   public Screen screen;", 1)
    cache[rel] = s; changed.add(rel)

for rel in changed:
    open(os.path.join(ROOT, rel), "wb").write(cache[rel].encode("utf-8"))

print("sabit duzeltme:", applied, "| degisen dosya:", len(changed))
if skipped:
    print("ATLANAN (%d):" % len(skipped))
    for a, b in skipped[:60]: print("  ", a, "-", b)
